private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    byte b = bb.get();
    if (b < 0) {
        int octetsToRead = -b - 1;
        if (bb.remaining() < octetsToRead) {
            throw new IllegalArgumentException("Not enough bytes to decode a UTF-8 sequence");
        }
        for (int j = 0; j < octetsToRead; j++) {
            b = bb.get();
            if ((b & 0xC0) != 0x80) {
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
            }
            i = decodeUTF8Sequence(sb, i, b, octetsToRead - j);
        }
    } else {
        sb.append((char) b);
        i++;
    }
    return i;
}

private static int decodeUTF8Sequence(StringBuilder sb, int start, byte b, int remaining) {
    if (b >= 0) {
        throw new IllegalArgumentException("Invalid UTF-8 byte for continuation");
    }
    while (remaining > 0) {
        b = bb.get();
        if ((b & 0xC0) != 0x80) {
            throw new IllegalArgumentException("Invalid UTF-8 sequence");
        }
        start = decodeUTF8Sequence(sb, start, b, remaining - 1);
    }
    sb.append((char) decodeUTF8(sb, sb.length() - remaining, start));
    return start;
}

private static int decodeUTF8(StringBuilder sb, int end, int start) {
    int value = 0;
    int bits = 0;
    for (int i = end - 1; i >= start; i--) {
        value |= (sb.charAt(i) & 0x3F) << bits;
        bits += 6;
    }
    return value;
}
