public String format(LoggingEvent event) {
    StringBuilder sb = new StringBuilder();
    String[] conversionPattern = event.getConversionPattern().split("%");

    for (String pattern : conversionPattern) {
        if (pattern.startsWith("%")) {
            switch (pattern.replace("%", "")) {
                case "c":
                    sb.append(event.getLoggerName());
                    break;
                case "d":
                    sb.append(new java.util.Date().toString());
                    break;
                case "m":
                    sb.append(event.getMessage());
                    break;
                case "p":
                    sb.append(event.getLevel());
                    break;
                default:
                    sb.append(pattern);
            }
        } else {
            sb.append(pattern);
        }
    }

    return sb.toString();
}
