void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    int numVertices = target.getNumVertices();
    V[] vertices = (V[]) target.getVertices().toArray();

    if(numVertices <= 1){
        throw new IllegalArgumentException("Number of vertices must be greater than 1 to construct a complete bipartite graph.");
    }

    Set<V> set1 = new HashSet<V>();
    Set<V> set2 = new HashSet<V>();

    int count = 0;
    for(V vertex : vertices){
        if(count < numVertices / 2){
            set1.add(vertex);
        } else {
            set2.add(vertex);
        }
        count++;
    }

    for(V v1 : set1) {
        for(V v2 : set2) {
            target.addEdge(v1, v2);
        }
    }
}

