public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Check if the target graph is not null
    if (target == null) {
        throw new IllegalArgumentException("Target graph cannot be null");
    }

    // Check if the resultMap is not null
    if (resultMap == null) {
        throw new IllegalArgumentException("Result map cannot be null");
    }

    // Number of vertices in the bipartite graph
    int n = 5; // Example value, can be adjusted
    int m = 5; // Example value, can be adjusted

    // Clear the target graph
    target.clear();

    // Create n vertices for the first partition
    for (int i = 0; i < n; i++) {
        String vertexId = "V" + i;
        V vertex = resultMap.get(vertexId);
        if (vertex != null) {
            target.addVertex(vertex);
        } else {
            throw new IllegalArgumentException("Vertex not found in resultMap for id: " + vertexId);
        }
    }

    // Create m vertices for the second partition
    for (int i = 0; i < m; i++) {
        String vertexId = "V" + (n + i);
        V vertex = resultMap.get(vertexId);
        if (vertex != null) {
            target.addVertex(vertex);
        } else {
            throw new IllegalArgumentException("Vertex not found in resultMap for id: " + vertexId);
        }
    }

    // Create edges between vertices from the two partitions
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            String vertexId1 = "V" + i;
            String vertexId2 = "V" + (n + j);
            V vertex1 = resultMap.get(vertexId1);
            V vertex2 = resultMap.get(vertexId2);
            if (vertex1 != null && vertex2 != null) {
                target.addEdge(vertex1, vertex2);
            } else {
                throw new IllegalArgumentException("Vertex not found in resultMap for ids: " + vertexId1 + " and " + vertexId2);
            }
        }
    }
}
