static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be greater than 0");
    }

    // Extract year, month, and day components
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    // Determine the new day by adding dayStep
    day += dayStep - 1;

    // Handle month and year roll-over
    while (day > 31) {
        if (month == 12) {
            year++;
            month = 1;
        } else {
            month++;
        }
        day -= ((month == 2 && (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0))) || (month == 4 || month == 6 || month == 9 || month == 11)) ? 29 : 30;
    }

    // Adjust for earlier month if day becomes zero
    if (day == 0) {
        month--;
        day = ((month == 2 && (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0))) || (month == 4 || month == 6 || month == 9 || month == 11)) ? 29 : 30;
    }

    return year * 10000 + month * 100 + day;
}
