int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        return 0;
    }
    int size = 0;
    for (int i = 0; i < len; i++) {
        char c = str.charAt(index + i);
        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(c)) {
            if (i + 1 < len) {
                char low = str.charAt(index + i + 1);
                if (Character.isLowSurrogate(low)) {
                    size += 4;
                    i++;
                } else {
                    // Invalid surrogate pair, handle as 3 bytes
                    size += 3;
                }
            } else {
                // Incomplete surrogate pair, handle as 3 bytes
                size += 3;
            }
        } else {
            size += 3;
        }
    }
    return size;
}

