            lb.put((byte) len);
            lb.put((byte) len >> 8);
            for (int i = 0; i < len; i++) {
                char c = str.charAt(i);
                if (c <= 0x7F) {
                    lb.put((byte) c);
                } else if (c <= 0x7FF) {
                    lb.put((byte) (0xC0 | (c >> 6)));
                    lb.put((byte) (0x80 | (c & 0x3F)));
                } else if (c <= 0xFFFF) {
                    lb.put((byte) (0xE0 | (c >> 12)));
                    lb.put((byte) (0x80 | ((c >> 6) & 0x3F)));
                    lb.put((byte) (0x80 | (c & 0x3F)));
                } else {
                    lb.put((byte) (0xF0 | (c >> 18)));
                    lb.put((byte) (0x80 | ((c >> 12) & 0x3F)));
                    lb.put((byte) (0x80 | ((c >> 6) & 0x3F)));
                    lb.put((byte) (0x80 | (c & 0x3F)));
                }
            }
        }
    } catch (Exception e) {
        // Handle exceptions as needed
        e.printStackTrace();
    }
