private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    char firstChar = descriptor.charAt(0);
    if (firstChar == 'L' || firstChar == '[') {
        // Pop one type
        while (outputFrameStack.size() > 0) {
            outputFrameStack.pop();
            if (outputFrameStack.size() == 0) {
                break;
            }
        }
    } else if (firstChar == '(') {
        // Pop multiple types based on the descriptor
        int paramCount = 0;
        int i = 1;
        while (i < descriptor.length()) {
            char currentChar = descriptor.charAt(i);
            if (currentChar == ')') {
                break;
            } else if (currentChar == 'L' || currentChar == '[') {
                paramCount++;
                while (outputFrameStack.size() > 0) {
                    outputFrameStack.pop();
                    if (outputFrameStack.size() == 0) {
                        break;
                    }
                }
            } else if (currentChar == 'B' || currentChar == 'C' || currentChar == 'D' || currentChar == 'F' || currentChar == 'I' || currentChar == 'J' || currentChar == 'S' || currentChar == 'Z') {
                paramCount++;
            }
            i++;
        }
    } else {
        throw new IllegalArgumentException("Invalid descriptor format");
    }
