private void putAbstractTypes(final int start, final int end){
    if (start < 0 || end > currentFrame.size() || start >= end) {
        throw new IllegalArgumentException("Invalid start or end index");
    }

    for (int i = start; i < end; i++) {
        Object abstractType = currentFrame.get(i);
        if (abstractType instanceof Class<?> clazz) {
            stackMapTableEntries.add(getVerificationTypeInfoForClass(clazz));
        } else if (abstractType instanceof AbstractType<?> abstractTypeObj) {
            stackMapTableEntries.add(getVerificationTypeInfoForAbstractType(abstractTypeObj));
        } else {
            throw new IllegalArgumentException("Unsupported type in currentFrame");
        }
    }
}

private VerificationTypeInfo getVerificationTypeInfoForClass(Class<?> clazz) {
    if (clazz.isPrimitive()) {
        return new VerificationTypeInfoSimple(clazz.getName());
    } else {
        return new VerificationTypeInfoObject(clazz.getName());
    }
}

private VerificationTypeInfo getVerificationTypeInfoForAbstractType(AbstractType<?> abstractType) {
    switch (abstractType.getType()) {
        case "INTERFACE":
            return new VerificationTypeInfoObject(abstractType.getName());
        default:
            throw new IllegalArgumentException("Unsupported abstract type: " + abstractType.getType());
    }
}

