String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder sb = new StringBuilder();
    int replaceLength = 0;

    for (int i = 0; i < str.length(); i++) {
        char ch = str.charAt(i);

        if (ch == '\\' && i + 1 < str.length()) {
            char nextCh = str.charAt(i + 1);
            switch (nextCh) {
                case 'b':
                    sb.append('\b');
                    replaceLength += 2;
                    break;
                case 't':
                    sb.append('\t');
                    replaceLength += 2;
                    break;
                case 'n':
                    sb.append('\n');
                    replaceLength += 2;
                    break;
                case 'f':
                    sb.append('\f');
                    replaceLength += 2;
                    break;
                case 'r':
                    sb.append('\r');
                    replaceLength += 2;
                    break;
                case '\"':
                    sb.append('"');
                    replaceLength += 2;
                    break;
                case '\'':
                    sb.append('\'');
                    replaceLength += 2;
                    break;
                case '\\':
                    sb.append('\\');
                    replaceLength += 2;
                    break;
                default:
                    sb.append('\\');
                    sb.append(nextCh);
                    replaceLength += 2;
                    break;
            }
            i++; // Skip the next character as it's been processed
        } else {
            sb.append(ch);
        }
    }

    return sb.toString();
