private int removeUnusedNodes() {
    int removedCount = 0;
    Queue<CategoryNode> queue = new ArrayDeque<>();
    queue.offer(rootNode);

    while (!queue.isEmpty()) {
        CategoryNode currentNode = queue.poll();

        if (!currentNode.isActive()) {
            removeNode(currentNode);
            removedCount++;
        } else {
            for (CategoryNode childNode : currentNode.getChildren()) {
                queue.offer(childNode);
            }
        }
    }

    return removedCount;
}

private void removeNode(CategoryNode node) {
    node.getParent().removeChild(node);
    node=null;
}

