final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= classFileBuffer.length) {
        throw new IllegalArgumentException("Invalid CONSTANT_Utf8 entry index: " + constantPoolEntryIndex);
    }
    int utf8Index = classFileBuffer[constantPoolEntryIndex] & 0xFF;
    int length = classFileBuffer[utf8Index + 1] & 0xFF;
    if (length * 2 > charBuffer.length) {
        throw new IllegalArgumentException("charBuffer is too small to read the UTF-8 string");
    }
    int offset = utf8Index + 2;
    for (int i = 0; i < length; i++) {
        charBuffer[i * 2] = (char) ((classFileBuffer[offset++] & 0xFF) << 8);
        charBuffer[i * 2 + 1] = (char) (classFileBuffer[offset++] & 0xFF);
    }
    return new String(charBuffer, 0, length * 2);
}
