final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    if (constantPoolEntryIndex < 0) {
        throw new IllegalArgumentException("constantPoolEntryIndex must be non-negative");
    }
    if (charBuffer == null) {
        throw new IllegalArgumentException("charBuffer must not be null");
    }
    int offset = constantPoolEntryIndex * 2 + 2; // Each UTF-8 entry starts with 1 byte length and then the bytes
    if (offset + charBuffer.length > classFileBuffer.length) {
        throw new IllegalArgumentException("charBuffer is too small to hold the UTF-8 string");
    }

    int length = classFileBuffer[offset];
    offset++; // Move past the length byte

    for (int i = 0; i < length; i++) {
        charBuffer[i] = (char) classFileBuffer[offset++];
    }

    return new String(charBuffer, 0, length);
}
