        int utf8Index = classFileBuffer[constantPoolEntryIndex + 1] << 8 | classFileBuffer[constantPoolEntryIndex + 2];
        int stringLength = classFileBuffer[utf8Index] << 8 | classFileBuffer[utf8Index + 1];

        // Copy the UTF-8 string into the provided charBuffer
        for (int i = 0; i < stringLength; i++) {
            charBuffer[i] = (char) (classFileBuffer[utf8Index + 2 + i] & 0xFF);
        }

        // Convert the charBuffer to a String
        return new String(charBuffer, 0, stringLength);
    } catch (ArrayIndexOutOfBoundsException e) {
        // Handle the case where the constant pool entry index is out of bounds
        LOG.error("Invalid constant pool entry index: {}", constantPoolEntryIndex);
        return null;
