    if (constantPoolEntryIndex < 1 || constantPoolEntryIndex >= classFileBuffer.length) {
        throw new IllegalArgumentException("Invalid constant pool entry index: " + constantPoolEntryIndex);
    }

    int offset = classFileBuffer[constantPoolEntryIndex] * 256 + classFileBuffer[constantPoolEntryIndex + 1];
    int utf8Length = classFileBuffer[offset] * 256 + classFileBuffer[offset + 1];
    offset += 2;

    if (utf8Length > charBuffer.length) {
        throw new IllegalArgumentException("Buffer too small to read UTF-8 string of length: " + utf8Length);
    }

    for (int i = 0; i < utf8Length; i++) {
