protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Input set and graph cannot be null");
    }

    List<E> edgeList = new ArrayList<>(tour);
    Iterator<E> it = edgeList.iterator();

    if (!it.hasNext()) {
        return new DefaultGraphPath<>(graph, null, null, 0);
    }

    E startEdge = it.next();
    V startVertex = graph.getEdgeSource(startEdge);
    V endVertex = graph.getEdgeTarget(startEdge);

    DefaultGraphPath<V,E> path = new DefaultGraphPath<>(graph, null, startEdge, graph.getEdgeWeight(startEdge));

    while (it.hasNext()) {
        E edge = it.next();
        if (!endVertex.equals(graph.getEdgeSource(edge))) {
            throw new IllegalArgumentException("The edges in the input set do not form a valid tour");
        }
        path.add(edge, graph.getEdgeWeight(edge));
        endVertex = graph.getEdgeTarget(edge);
    }

    path.setTarget(endVertex);
    return path;
}

