protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    List<E> edges = new ArrayList<>(tour);
    if (edges.isEmpty()) {
        return graph.createEmptyPath();
    }

    V startVertex = edges.get(0).getEndpoint(0);
    V currentVertex = startVertex;
    List<E> pathEdges = new ArrayList<>();
    pathEdges.add(graph.getEdge(edges.get(0).getEndpoint(0), edges.get(0).getEndpoint(1)));

    for (int i = 1; i < edges.size(); i++) {
        E edge = edges.get(i);
        V nextVertex;
        if (edge.getEndpoint(0).equals(currentVertex)) {
            nextVertex = edge.getEndpoint(1);
        } else {
            nextVertex = edge.getEndpoint(0);
        }
        pathEdges.add(edge);
        currentVertex = nextVertex;
    }

    return graph.createPath(startVertex, pathEdges);
}
