protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || tour.isEmpty()) {
        throw new IllegalArgumentException("Tour set cannot be null or empty");
    }
    if (graph == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }

    List<E> edgeList = new ArrayList<>(tour);
    List<V> vertexList = new ArrayList<>();

    Vertex<V, E> startVertex = null;
    for (E edge : edgeList) {
        if (startVertex == null) {
            startVertex = graph.getEdgeSource(edge);
        }
        Vertex<V, E> endVertex = graph.getEdgeTarget(edge);
        if (!vertexList.contains(startVertex)) {
            vertexList.add(startVertex);
        }
        vertexList.add(endVertex);
        startVertex = endVertex;
    }

    // Ensure the tour is closed
    if (!vertexList.get(0).equals(vertexList.get(vertexList.size() - 1))) {
        throw new IllegalArgumentException("Tour is not closed");
    }

    return new GraphWalk<>(graph, vertexList);
}
