protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || tour.isEmpty()) {
        throw new IllegalArgumentException("Tour cannot be null or empty");
    }

    if (graph == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }

    List<E> tourList = new ArrayList<>(tour);
    V currentNode = tourList.get(0).getEndpoint1();
    List<V> pathVertices = new ArrayList<>();
    pathVertices.add(currentNode);

    for (int i = 1; i < tourList.size(); i++) {
        E edge = tourList.get(i - 1);
        V nextNode = edge.getEndpoint1().equals(currentNode) ? edge.getEndpoint2() : edge.getEndpoint1();
        pathVertices.add(nextNode);
        currentNode = nextNode;
    }

    pathVertices.add(pathVertices.get(0)); // Add the starting node again to close the path

    List<E> pathEdges = new ArrayList<>();
    for (int i = 0; i < pathVertices.size() - 1; i++) {
        edge = graph.getEdge(pathVertices.get(i), pathVertices.get(i + 1));
        if (edge == null) {
            throw new IllegalArgumentException("The given tour is not valid for the specified graph");
        }
        pathEdges.add(edge);
    }

    return new GraphPath<>(graph, pathVertices, pathEdges, graph.distance(pathVertices.get(0), pathVertices.get(pathVertices.size() - 1)));
}
