public int addConstantNameAndType(final String name, final String descriptor) {
    int index = findNameAndType(name, descriptor);
    if (index != -1) {
        return index;
    }
    int newIndex = maxPoolSize;
    maxPoolSize++;
    types[newIndex] = NAME_TYPE;
    utf8s[newIndex] = name;
    utf8s[maxPoolSize] = descriptor;
    maxPoolSize++;
