private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("Invalid minLabel: " + minLabel);
    }

    Set<Integer> minBucket = bucketsByLabel.get(minLabel);
    if (minBucket.isEmpty()) {
        return;
    }

    for (int vertex : minBucket) {
        int newLabel = labels.indexOf(vertex);
        if (newLabel != -1) {
            labels.set(newLabel, 0);
        } else {
            throw new IllegalStateException("Vertex " + vertex + " not found in labels");
        }
        bucketsByLabel.get(0).add(vertex);
    }

    minBucket.clear();
}
