        // node is the head of the list
        list.setHead(node.getNext());
    }
    if (node.getNext() != null) {
        node.getNext().setPrevious(node.getPrevious());
    } else {
        // node is the tail of the list
        list.setTail(node.getPrevious());
    }
    node.setNext(null);
    node.setPrevious(null);
    list.setSize(list.getSize() - 1);
}

private void addListNode(ListNode<E> node) {
    if (list.getTail() != null) {
        list.getTail().setNext(node);
        node.setPrevious(list.getTail());
    } else {
        // list is empty
        list.setHead(node);
    }
    list.setTail(node);
    list.setSize(list.getSize() + 1);
}
