String function(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath cannot be null");
    }

    // Normalize the paths to absolute paths
    path = new File(path).getAbsolutePath();
    relativePath = new File(relativePath).getAbsolutePath();

    // Replace backslashes with slashes
    path = path.replace("\\", "/");
    relativePath = relativePath.replace("\\", "/");

    // Split the paths into components
    String[] pathComponents = path.split("/");
    String[] relativeComponents = relativePath.split("/");

    // Build the resulting path
    StringBuilder result = new StringBuilder();
    int i = 0;

    // Process relative path components
    while (i < relativeComponents.length) {
        if (relativeComponents[i].equals("..")) {
            // Move up one level in the path if possible
            if (!pathComponents.isEmpty()) {
                pathComponents.remove(pathComponents.length - 1);
            }
        } else if (!relativeComponents[i].isEmpty()) {
            // Add the component to the path
            pathComponents.add(relativeComponents[i]);
        }
        i++;
    }

    // Combine the remaining path components
    for (String component : pathComponents) {
        if (result.length() > 0) {
            result.append("/");
        }
        result.append(component);
    }

    return result.toString();
}
