public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath cannot be null");
    }

    // Add a trailing slash to the path if it doesn't already have one
    if (!path.endsWith("/")) {
        path += "/";
    }

    // Remove any leading "./" from the relativePath
    relativePath = relativePath.replaceFirst("^\\.\\/", "");

    // Combine the path and relativePath
    String fullPath = path + relativePath;

    // Normalize the fullPath to handle any ".." or redundant slashes
    fullPath = fullPath.replaceAll("/+", "/");

    return fullPath;
}
