List<ThreadSnapshot> function(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    BufferedReader reader = new BufferedReader(new FileReader(file));
    String line;
    while ((line = reader.readLine()) != null) {
        String[] parts = line.split(",");
        if (parts.length < 5) {
            continue;
        }
        long timestamp = Long.parseLong(parts[0]);
        String threadName = parts[1];
        int threadId = Integer.parseInt(parts[2]);
        String stackTrace = parts[3];
        long duration = Long.parseLong(parts[4]);

        for (ProfileAnalyzeTimeRange range : timeRanges) {
            if (timestamp >= range.getStart() && timestamp <= range.getEnd()) {
                ThreadSnapshot snapshot = new ThreadSnapshot(timestamp, threadName, threadId, stackTrace, duration);
                snapshots.add(snapshot);
                break;
            }
        }
    }
    reader.close();
    return snapshots;
}
